:where([data-moru-registry]) .ui-carousel {
  min-width: 0;
  max-width: 100%;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-body-size);
  line-height: var(--ui-type-body-line-height);
  letter-spacing: var(--ui-type-body-letter-spacing);
}
:where([data-moru-registry]) .ui-carousel {
  display: grid;
  gap: var(--ui-field-gap);
}
:where([data-moru-registry]) .ui-carousel-viewport {
  overflow: hidden;
  border-radius: var(--ui-radius);
  outline: none;
}
:where([data-moru-registry]) .ui-carousel-viewport:focus-visible {
  outline: 2px solid var(--ui-focus-ring);
  outline-offset: 3px;
}
:where([data-moru-registry]) .ui-carousel-track {
  display: flex;
  touch-action: pan-y pinch-zoom;
}
:where([data-moru-registry]) .ui-carousel-slide {
  min-width: 0;
  flex: 0 0 100%;
}
:where([data-moru-registry]) .ui-carousel[data-orientation='vertical'] .ui-carousel-viewport {
  height: 200px;
}
:where([data-moru-registry]) .ui-carousel[data-orientation='vertical'] .ui-carousel-track {
  flex-direction: column;
  height: 100%;
  touch-action: pan-x pinch-zoom;
}
:where([data-moru-registry]) .ui-carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--ui-control-gap);
}
:where([data-moru-registry]) .ui-carousel-controls > span {
  font-size: var(--ui-type-caption-size);
  color: var(--ui-muted);
  font-variant-numeric: tabular-nums;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { useCallback, useEffect, useId, useState, type ReactNode } from 'react'
import useEmblaCarousel from 'embla-carousel-react'
import { ArrowLeft, ArrowRight } from 'lucide-react'
import { Button } from './button'
import { cn } from './_lib/cn'
import './carousel.css'

export interface CarouselItem {
  id: string
  content: ReactNode
  label?: string
}
export interface CarouselProps {
  items: CarouselItem[]
  loop?: boolean
  disabled?: boolean
  orientation?: 'horizontal' | 'vertical'
  direction?: 'ltr' | 'rtl'
  onValueChange?: (index: number) => void
  className?: string
  'aria-label': string
}

export function Carousel({
  items,
  loop = false,
  disabled = false,
  orientation = 'horizontal',
  direction = 'ltr',
  onValueChange,
  className,
  'aria-label': label,
}: CarouselProps) {
  const { t } = useI18n()

  const id = useId()
  const [viewportRef, api] = useEmblaCarousel({
    loop,
    axis: orientation === 'vertical' ? 'y' : 'x',
    direction,
    watchDrag: !disabled,
  })
  const [selection, setSelection] = useState({ index: 0, previous: false, next: false })
  const update = useCallback(() => {
    if (!api) return
    setSelection({
      index: api.selectedScrollSnap(),
      previous: api.canScrollPrev(),
      next: api.canScrollNext(),
    })
  }, [api])
  useEffect(() => {
    if (!api) return
    update()
    const select = () => {
      update()
      onValueChange?.(api.selectedScrollSnap())
    }
    api.on('select', select).on('reInit', update)
    return () => {
      api.off('select', select).off('reInit', update)
    }
  }, [api, update, onValueChange])
  return (
    <section
      className={cn('ui-carousel', className)}
      role="region"
      aria-roledescription={t('캐러셀')}
      aria-label={label}
      data-orientation={orientation}
      dir={direction}
      onKeyDown={(event) => {
        if (
          disabled ||
          event.defaultPrevented ||
          (event.target instanceof HTMLElement &&
            event.target.closest(
              'input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="combobox"],[role="slider"],[role="tab"],[role="menuitem"],[role="radio"]',
            ))
        )
          return
        const previous =
          orientation === 'vertical' ? 'ArrowUp' : direction === 'rtl' ? 'ArrowRight' : 'ArrowLeft'
        const next =
          orientation === 'vertical'
            ? 'ArrowDown'
            : direction === 'rtl'
              ? 'ArrowLeft'
              : 'ArrowRight'
        if (event.key === previous) {
          event.preventDefault()
          api?.scrollPrev()
        } else if (event.key === next) {
          event.preventDefault()
          api?.scrollNext()
        }
      }}
    >
      <div
        ref={viewportRef}
        className="ui-carousel-viewport"
        id={`${id}-viewport`}
        tabIndex={disabled ? -1 : 0}
      >
        <div className="ui-carousel-track">
          {items.map((item, index) => (
            <div
              className="ui-carousel-slide"
              key={item.id}
              role="group"
              aria-roledescription={t('슬라이드')}
              aria-label={item.label ?? `${index + 1} / ${items.length}`}
              inert={index !== selection.index}
            >
              {item.content}
            </div>
          ))}
        </div>
      </div>
      <div className="ui-carousel-controls">
        <Button
          size="sm"
          variant="secondary"
          aria-label={t('이전 슬라이드')}
          aria-controls={`${id}-viewport`}
          disabled={disabled || !selection.previous}
          onClick={() => api?.scrollPrev()}
        >
          <ArrowLeft size={15} />
        </Button>
        <span role="status" aria-live="polite">
          {items.length ? selection.index + 1 : 0} / {items.length}
        </span>
        <Button
          size="sm"
          variant="secondary"
          aria-label={t('다음 슬라이드')}
          aria-controls={`${id}-viewport`}
          disabled={disabled || !selection.next}
          onClick={() => api?.scrollNext()}
        >
          <ArrowRight size={15} />
        </Button>
      </div>
    </section>
  )
}
